routines.source_code:
DECLARE
    project_key TEXT;
    next_num INTEGER;
BEGIN
    -- Get project key
    SELECT key INTO project_key FROM projects WHERE id = NEW.project_id;

    -- Get next number for this project
    SELECT COALESCE(MAX(
        CASE
            WHEN code ~ ('^' || project_key || '-[0-9]+$')
            THEN CAST(SUBSTRING(code FROM LENGTH(project_key) + 2) AS INTEGER)
            ELSE 0
        END
    ), 0) + 1 INTO next_num
    FROM tickets
    WHERE project_id = NEW.project_id;

    -- Set the code
    NEW.code := project_key || '-' || next_num;

    RETURN NEW;
END;

DECLARE
    affected_project_id bigint;
BEGIN
    IF OLD.status_group IS NOT DISTINCT FROM NEW.status_group THEN
        RETURN NEW;
    END IF;

    FOR affected_project_id IN
        SELECT DISTINCT t.project_id
        FROM public.tickets t
        WHERE t.column_id = NEW.id
          AND t.is_deleted = FALSE
    LOOP
        PERFORM public.refresh_project_performance_counters(affected_project_id);
    END LOOP;

    RETURN NEW;
END;

