BEGIN
    -- Update comments count
    IF TG_TABLE_NAME = 'ticket_comments' THEN
        IF TG_OP = 'INSERT' AND NEW.is_deleted = FALSE THEN
            UPDATE tickets SET comments_count = comments_count + 1 WHERE id = NEW.ticket_id;
        ELSIF TG_OP = 'UPDATE' AND OLD.is_deleted = FALSE AND NEW.is_deleted = TRUE THEN
            UPDATE tickets SET comments_count = GREATEST(0, comments_count - 1) WHERE id = NEW.ticket_id;
        ELSIF TG_OP = 'DELETE' AND OLD.is_deleted = FALSE THEN
            UPDATE tickets SET comments_count = GREATEST(0, comments_count - 1) WHERE id = OLD.ticket_id;
        END IF;
    END IF;

    -- Update attachments count
    IF TG_TABLE_NAME = 'ticket_attachments' THEN
        IF TG_OP = 'INSERT' THEN
            UPDATE tickets SET attachments_count = attachments_count + 1 WHERE id = NEW.ticket_id;
        ELSIF TG_OP = 'DELETE' THEN
            UPDATE tickets SET attachments_count = GREATEST(0, attachments_count - 1) WHERE id = OLD.ticket_id;
        END IF;
    END IF;

    -- Update checklists count
    IF TG_TABLE_NAME = 'ticket_checklists' THEN
        IF TG_OP = 'INSERT' THEN
            UPDATE tickets SET
                checklists_count = checklists_count + 1,
                checklists_completed = checklists_completed + CASE WHEN NEW.is_completed THEN 1 ELSE 0 END
            WHERE id = NEW.ticket_id;
        ELSIF TG_OP = 'UPDATE' AND OLD.is_completed != NEW.is_completed THEN
            UPDATE tickets SET
                checklists_completed = checklists_completed + CASE WHEN NEW.is_completed THEN 1 ELSE -1 END
            WHERE id = NEW.ticket_id;
        ELSIF TG_OP = 'DELETE' THEN
            UPDATE tickets SET
                checklists_count = GREATEST(0, checklists_count - 1),
                checklists_completed = GREATEST(0, checklists_completed - CASE WHEN OLD.is_completed THEN 1 ELSE 0 END)
            WHERE id = OLD.ticket_id;
        END IF;
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
